namespace ClaimCore.ContractGeneration

open System.Text
open System.Text.Json
open ClaimCore.ClientProtocol
open ClaimCore.Contracts

/// Test-only schema extension, generated by the same catalogue and decoder entry points.
module ContractExtension =
    let operation = "SYNTHETIC_CORRECTION"
    let private token value = Schema.constant (TextConstant value)
    let private property name value = Schema.property name value true
    let private objectOf values = Schema.objectOf false values
    let private text = Schema.string None None (Some 1) None
    let private uuid = Schema.string (Some "uuid") None None None
    let private revision = Schema.integer (Some 0L) (Some 9007199254740991L)

    let private document name root =
        {
            Identifier = "https://claimcore.local/contracts/extension." + name
            Title = "Test extension " + name
            Root = root
            Definitions = []
        }

    let request =
        objectOf
            [
                property "operationId" uuid
                property "caseReference" text
                property "expectedRevision" revision
                property
                    "act"
                    (objectOf
                        [
                            property "kind" (token operation)
                            property
                                "groups"
                                (objectOf
                                    [
                                        property
                                            "syntheticGroup"
                                            (Schema.oneOf
                                                [
                                                    objectOf
                                                        [
                                                            property "mode" (token "REPLACE")
                                                            property
                                                                "values"
                                                                (objectOf
                                                                    [
                                                                        property
                                                                            "syntheticText"
                                                                            text
                                                                    ])
                                                        ]
                                                    objectOf [ property "mode" (token "KEEP") ]
                                                ])
                                    ])
                        ])
            ]
        |> document "request"

    let private response identifier tag data =
        objectOf
            [
                property "endpoint" (token identifier)
                property "operationId" uuid
                property "outcome" (objectOf [ property "tag" (token tag); property "data" data ])
            ]
        |> document (identifier + ".response")

    let private receipt =
        objectOf
            [
                property "operationId" uuid
                property "scope" (token "CASE")
                property "act" (token operation)
                property "caseReference" text
                property "revision" (Schema.integer (Some 1L) (Some 9007199254740991L))
            ]

    let endpoints =
        let make identifier mutates reply =
            {
                Identifier = identifier
                Method = "POST"
                Path = "/api/" + identifier
                Mutates = mutates
                AcceptingScope = if mutates then "CASE" else "NONE"
                ReceiptScope = "CASE"
                Request = request
                Response = reply
            }

        [
            make
                "extension.preview"
                false
                (response
                    "extension.preview"
                    "REVIEWED"
                    (objectOf
                        [
                            property
                                "review"
                                (objectOf
                                    [
                                        property
                                            "after"
                                            (objectOf
                                                [
                                                    property "caseReference" text
                                                    property
                                                        "revision"
                                                        (Schema.integer
                                                            (Some 1L)
                                                            (Some 9007199254740991L))
                                                ])
                                    ])
                        ]))
            make "extension.execute" true (response "extension.execute" "ACCEPTED" receipt)
        ]

    let private descriptors =
        JsonSerializer.SerializeToUtf8Bytes
            {|
                commands =
                    [
                        {|
                            kind = operation
                            requestSchema = request.Identifier
                        |}
                    ]
            |}

    let private catalogue () =
        let metadata = EndpointCatalog.metadataFor endpoints |> CanonicalContract.text
        Encoding.UTF8.GetBytes("{\"endpoints\":" + metadata + "}")

    let native () =
        NativeCatalogue.sourceFor "ClaimCore.ContractExtension" endpoints descriptors (catalogue ())

    let browser () =
        Array.append
            (BrowserArtifacts.sourceFor endpoints)
            (Encoding.UTF8.GetBytes(
                "\nexport const extensionOperation = "
                + JsonSerializer.Serialize(operation)
                + ";\n"
            ))
